import{_ as a,c as s,o,j as i,Y as n,t as r}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"gitnamespaces | x-cmd man (git man7) | Git namespaces","titleTemplate":false,"description":"x-cmd man (git man7 Manual Page) | gitnamespaces - Git namespaces","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"gitnamespaces | x-cmd man (git man7) | Git namespaces"}],["meta",{"name":"og:description","content":"x-cmd man (git man7 Manual Page) | gitnamespaces - Git namespaces"}]]},"headers":[],"params":{"isMan":true,"man":"gitnamespaces","category":"git man7","desc":"Git namespaces"},"relativePath":"git/man7/gitnamespaces.md","filePath":"git/man7/[man].md"}'),c={name:"git/man7/gitnamespaces.md"},p={class:"visually-hidden"};function h(t,e,l,d,g,m){return o(),s("div",null,[i("h1",p,r(t.$params.man),1),e[0]||(e[0]=n(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>gitnamespaces - Git namespaces</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GIT_NAMESPACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">namespace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upload-pack</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GIT_NAMESPACE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">namespace</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> receive-pack</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Git supports dividing the refs of a single repository into multiple namespaces, each of which has its own branches, tags, and HEAD. Git can expose each namespace as an independent repository to pull from and push to, while sharing the object store, and exposing all the refs to operations such as <strong>git-gc</strong>(1).</p><p>Storing multiple repositories as namespaces of a single repository avoids storing duplicate copies of the same objects, such as when storing multiple branches of the same source. The alternates mechanism provides similar support for avoiding duplicates, but alternates do not prevent duplication between new objects added to the repositories without ongoing maintenance, while namespaces do.</p><p>To specify a namespace, set the <strong>GIT_NAMESPACE</strong> environment variable to the namespace. For each ref namespace, Git stores the corresponding refs in a directory under <strong>refs/namespaces/</strong>. For example, <strong>GIT_NAMESPACE=foo</strong> will store refs under <strong>refs/namespaces/foo/</strong>. You can also specify namespaces via the <strong>--namespace</strong> option to <strong>git</strong>(1).</p><p>Note that namespaces which include a <strong>/</strong> will expand to a hierarchy of namespaces; for example, <strong>GIT_NAMESPACE=foo/bar</strong> will store refs under <strong>refs/namespaces/foo/refs/namespaces/bar/</strong>. This makes paths in <strong>GIT_NAMESPACE</strong> behave hierarchically, so that cloning with <strong>GIT_NAMESPACE=foo/bar</strong> produces the same result as cloning with <strong>GIT_NAMESPACE=foo</strong> and cloning from that repo with <strong>GIT_NAMESPACE=bar</strong>. It also avoids ambiguity with strange namespace paths such as <strong>foo/refs/heads/</strong>, which could otherwise generate directory/file conflicts within the <strong>refs</strong> directory.</p><p><strong>git-upload-pack</strong>(1) and <strong>git-receive-pack</strong>(1) rewrite the names of refs as specified by <strong>GIT_NAMESPACE</strong>. git-upload-pack and git-receive-pack will ignore all references outside the specified namespace.</p><p>The smart HTTP server, <strong>git-http-backend</strong>(1), will pass GIT_NAMESPACE through to the backend programs; see <strong>git-http-backend</strong>(1) for sample configuration to expose repository namespaces as repositories.</p><p>For a simple local test, you can use <strong>git-remote-ext</strong>(1):</p><blockquote><pre><code>git clone ext::&#39;git --namespace=foo %s /tmp/prefixed.git&#39;
</code></pre></blockquote><h2 id="security" tabindex="-1">SECURITY <a class="header-anchor" href="#security" aria-label="Permalink to &quot;SECURITY&quot;">​</a></h2><p>The fetch and push protocols are not designed to prevent one side from stealing data from the other repository that was not intended to be shared. If you have private data that you need to protect from a malicious peer, your best option is to store it in another repository. This applies to both clients and servers. In particular, namespaces on a server are not effective for read access control; you should only grant read access to a namespace to clients that you would trust with read access to the entire repository.</p><p>The known attack vectors are as follows:</p><blockquote><p>1.</p><p>The victim sends &quot;have&quot; lines advertising the IDs of objects it has that are not explicitly intended to be shared but can be used to optimize the transfer if the peer also has them. The attacker chooses an object ID X to steal and sends a ref to X, but isn&#39;t required to send the content of X because the victim already has it. Now the victim believes that the attacker has X, and it sends the content of X back to the attacker later. (This attack is most straightforward for a client to perform on a server, by creating a ref to X in the namespace the client has access to and then fetching it. The most likely way for a server to perform it on a client is to &quot;merge&quot; X into a public branch and hope that the user does additional work on this branch and pushes it back to the server without noticing the merge.)</p></blockquote><blockquote><p>2.</p><p>As in #1, the attacker chooses an object ID X to steal. The victim sends an object Y that the attacker already has, and the attacker falsely claims to have X and not Y, so the victim sends Y as a delta against X. The delta reveals regions of X that are similar to Y to the attacker.</p></blockquote><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,20))])}const k=a(c,[["render",h]]);export{f as __pageData,k as default};
